490	  DenseMap<JITDylib *, SymbolLookupSet> InitFunctions;
491	  DenseMap<JITDylib *, SymbolLookupSet> DeInitFunctions;
492	  ItaniumCXAAtExitSupport AtExitMgr;
493	};
