1130	class LoadAndLinkDynLibrary {
1131	public:
1132	  LoadAndLinkDynLibrary(LLJIT &J) : J(J) {}
1133	  Error operator()(JITDylib &JD, StringRef DLLName) {
1134	    if (!DLLName.ends_with_insensitive(".dll"))
1135	      return make_error<StringError>("DLLName not ending with .dll",
1136	                                     inconvertibleErrorCode());
1137	    auto DLLNameStr = DLLName.str(); // Guarantees null-termination.
1138	    auto DLLJD = J.loadPlatformDynamicLibrary(DLLNameStr.c_str());
1139	    if (!DLLJD)
1140	      return DLLJD.takeError();
1141	    JD.addToLinkOrder(*DLLJD);
1142	    return Error::success();
1143	  }
1144	
1145	private:
1146	  LLJIT &J;
1147	};
