1149	Expected<JITDylibSP> ExecutorNativePlatform::operator()(LLJIT &J) {
1150	  auto ProcessSymbolsJD = J.getProcessSymbolsJITDylib();
1151	  if (!ProcessSymbolsJD)
1152	    return make_error<StringError>(
1153	        "Native platforms require a process symbols JITDylib",
1154	        inconvertibleErrorCode());
1155	
1156	  const Triple &TT = J.getTargetTriple();
1157	  ObjectLinkingLayer *ObjLinkingLayer =
1158	      dyn_cast<ObjectLinkingLayer>(&J.getObjLinkingLayer());
1159	
1160	  if (!ObjLinkingLayer)
1161	    return make_error<StringError>(
1162	        "ExecutorNativePlatform requires ObjectLinkingLayer",
1163	        inconvertibleErrorCode());
1164	
1165	  std::unique_ptr<MemoryBuffer> RuntimeArchiveBuffer;
1166	  if (OrcRuntime.index() == 0) {
1167	    auto A = errorOrToExpected(MemoryBuffer::getFile(std::get<0>(OrcRuntime)));
1168	    if (!A)
1169	      return A.takeError();
1170	    RuntimeArchiveBuffer = std::move(*A);
1171	  } else
1172	    RuntimeArchiveBuffer = std::move(std::get<1>(OrcRuntime));
1173	
1174	  auto &ES = J.getExecutionSession();
1175	  auto &PlatformJD = ES.createBareJITDylib("<Platform>");
1176	  PlatformJD.addToLinkOrder(*ProcessSymbolsJD);
1177	
1178	  J.setPlatformSupport(std::make_unique<ORCPlatformSupport>(J));
1179	
1180	  switch (TT.getObjectFormat()) {
1181	  case Triple::COFF: {
1182	    const char *VCRuntimePath = nullptr;
1183	    bool StaticVCRuntime = false;
1184	    if (VCRuntime) {
1185	      VCRuntimePath = VCRuntime->first.c_str();
1186	      StaticVCRuntime = VCRuntime->second;
1187	    }
1188	    if (auto P = COFFPlatform::Create(
1189	            *ObjLinkingLayer, PlatformJD, std::move(RuntimeArchiveBuffer),
1190	            LoadAndLinkDynLibrary(J), StaticVCRuntime, VCRuntimePath))
1191	      J.getExecutionSession().setPlatform(std::move(*P));
1192	    else
1193	      return P.takeError();
1194	    break;
1195	  }
1196	  case Triple::ELF: {
1197	    auto G = StaticLibraryDefinitionGenerator::Create(
1198	        *ObjLinkingLayer, std::move(RuntimeArchiveBuffer));
1199	    if (!G)
1200	      return G.takeError();
1201	
1202	    if (auto P =
1203	            ELFNixPlatform::Create(*ObjLinkingLayer, PlatformJD, std::move(*G)))
1204	      J.getExecutionSession().setPlatform(std::move(*P));
1205	    else
1206	      return P.takeError();
1207	    break;
1208	  }
1209	  case Triple::MachO: {
1210	    auto G = StaticLibraryDefinitionGenerator::Create(
1211	        *ObjLinkingLayer, std::move(RuntimeArchiveBuffer));
1212	    if (!G)
1213	      return G.takeError();
1214	
1215	    if (auto P =
1216	            MachOPlatform::Create(*ObjLinkingLayer, PlatformJD, std::move(*G)))
1217	      ES.setPlatform(std::move(*P));
1218	    else
1219	      return P.takeError();
1220	    break;
1221	  }
1222	  default:
1223	    return make_error<StringError>("Unsupported object format in triple " +
1224	                                       TT.str(),
1225	                                   inconvertibleErrorCode());
1226	  }
1227	
1228	  return &PlatformJD;
1229	}
