1323	LLLazyJIT::LLLazyJIT(LLLazyJITBuilderState &S, Error &Err) : LLJIT(S, Err) {
1324	
1325	  // If LLJIT construction failed then bail out.
1326	  if (Err)
1327	    return;
1328	
1329	  ErrorAsOutParameter _(&Err);
1330	
1331	  /// Take/Create the lazy-compile callthrough manager.
1332	  if (S.LCTMgr)
1333	    LCTMgr = std::move(S.LCTMgr);
1334	  else {
1335	    if (auto LCTMgrOrErr = createLocalLazyCallThroughManager(
1336	            S.TT, *ES, S.LazyCompileFailureAddr))
1337	      LCTMgr = std::move(*LCTMgrOrErr);
1338	    else {
1339	      Err = LCTMgrOrErr.takeError();
1340	      return;
1341	    }
1342	  }
1343	
1344	  // Take/Create the indirect stubs manager builder.
1345	  auto ISMBuilder = std::move(S.ISMBuilder);
1346	
1347	  // If none was provided, try to build one.
1348	  if (!ISMBuilder)
1349	    ISMBuilder = createLocalIndirectStubsManagerBuilder(S.TT);
1350	
1351	  // No luck. Bail out.
1352	  if (!ISMBuilder) {
1353	    Err = make_error<StringError>("Could not construct "
1354	                                  "IndirectStubsManagerBuilder for target " +
1355	                                      S.TT.str(),
1356	                                  inconvertibleErrorCode());
1357	    return;
1358	  }
1359	
1360	  // Create the IP Layer.
1361	  IPLayer = std::make_unique<IRPartitionLayer>(*ES, *InitHelperTransformLayer);
1362	
1363	  // Create the COD layer.
1364	  CODLayer = std::make_unique<CompileOnDemandLayer>(*ES, *IPLayer, *LCTMgr,
1365	                                                    std::move(ISMBuilder));
1366	
1367	  if (*S.SupportConcurrentCompilation)
1368	    CODLayer->setCloneToNewContextOnEmit(true);
1369	}
